<?php
$pdo=db();$canManage=in_array($user['role'],['Administrator','Head'],true);$termRows=$pdo->query('SELECT id,name,academic_year,is_current FROM school_terms ORDER BY is_current DESC,academic_year DESC,term_number DESC')->fetchAll();$termId=filter_var($_GET['term_id']??null,FILTER_VALIDATE_INT);if(!$termId)foreach($termRows as $t)if($t['is_current']){$termId=(int)$t['id'];break;}if(!$termId&&$termRows)$termId=(int)$termRows[0]['id'];$term=null;foreach($termRows as $t)if((int)$t['id']===$termId)$term=$t;
$classId=filter_var($_GET['class_id']??null,FILTER_VALIDATE_INT);$class=null;foreach($classes as $c)if((int)$c['id']===$classId)$class=$c;if(!$class&&$classes){$class=$classes[0];$classId=(int)$class['id'];}
$allocationRows=[];$slots=[];$selectedClassSubjects=[];$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday'];
if($class&&$term&&(int)$class['academic_year']===(int)$term['academic_year']){$stmt=$pdo->prepare('SELECT cs.id,cs.teacher_id,c.class_teacher_id,s.subject_name,s.subject_code,COALESCE(cs.teacher_id,c.class_teacher_id) AS assigned_teacher,u.full_name AS teacher_name FROM class_subjects cs JOIN class_groups c ON c.id=cs.class_id JOIN subjects s ON s.id=cs.subject_id LEFT JOIN users u ON u.id=COALESCE(cs.teacher_id,c.class_teacher_id) WHERE cs.class_id=:class AND s.active=1 ORDER BY s.subject_name');$stmt->execute(['class'=>$classId]);$allocationRows=$stmt->fetchAll();foreach($allocationRows as $a)$selectedClassSubjects[(int)$a['id']]=true;$slotSql='SELECT ts.*,s.subject_name,s.subject_code,u.full_name AS teacher_name FROM timetable_slots ts JOIN class_subjects cs ON cs.id=ts.class_subject_id JOIN subjects s ON s.id=cs.subject_id LEFT JOIN users u ON u.id=ts.teacher_id WHERE ts.term_id=:term AND ts.class_id=:class';$slotParams=['term'=>$termId,'class'=>$classId];if($user['role']==='Teacher'){$slotSql.=' AND (ts.teacher_id=:teacher OR EXISTS (SELECT 1 FROM class_groups cg WHERE cg.id=ts.class_id AND cg.class_teacher_id=:class_teacher))';$slotParams+=['teacher'=>$user['id'],'class_teacher'=>$user['id']];}$slotSql.=' ORDER BY ts.weekday,ts.starts_at,ts.period_number';$stmt=$pdo->prepare($slotSql);$stmt->execute($slotParams);$slots=$stmt->fetchAll();}
?>
<div class="page-heading"><div><div class="eyebrow">SCHOOL DAY</div><h1>Timetable</h1><p class="subheading">Plan class periods and check teacher and venue availability for each term.</p></div></div>
<?php if(!$termRows||!$classes): ?><section class="panel empty-state"><h2>Set up terms, classes and subjects</h2><p>Timetables need an academic term, class group and subject allocations.</p><a class="primary-button" href="?page=academics&tab=classes">Configure academics</a></section><?php else: ?>
<form method="get" class="report-filter"><input type="hidden" name="page" value="academics"><input type="hidden" name="tab" value="timetable"><label>Term<select name="term_id"><?php foreach($termRows as $t): ?><option value="<?= (int)$t['id'] ?>" <?= $termId===(int)$t['id']?'selected':'' ?>><?= h($t['name']) ?> · <?= (int)$t['academic_year'] ?></option><?php endforeach; ?></select></label><label>Class<select name="class_id"><?php foreach($classes as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $classId===(int)$c['id']?'selected':'' ?>>Form <?= (int)$c['form_level'] ?><?= h($c['stream']) ?> · <?= (int)$c['academic_year'] ?></option><?php endforeach; ?></select></label><button class="outline-button">View timetable</button></form>
<?php if(!$class||!$term||(int)$class['academic_year']!==(int)$term['academic_year']): ?><div class="alert alert-warn">Choose a term and class from the same academic year.</div><?php else: ?>
<?php if($canManage): ?><section class="panel settings-panel"><h2>Add a timetable period</h2><p>Periods with overlapping class, teacher or venue times cannot be saved.</p><?php if(!$allocationRows): ?><div class="alert alert-warn">Assign subjects to this class before creating timetable periods.</div><?php else: ?><form method="post" action="actions/timetable_slot_save.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><input type="hidden" name="operation" value="create"><input type="hidden" name="term_id" value="<?= (int)$termId ?>"><input type="hidden" name="class_id" value="<?= (int)$classId ?>"><label>Subject & teacher<select name="class_subject_id" required><?php foreach($allocationRows as $a): ?><option value="<?= (int)$a['id'] ?>"><?= h($a['subject_name']) ?><?= $a['teacher_name']?' · '.h($a['teacher_name']):' · Teacher unassigned' ?></option><?php endforeach; ?></select></label><label>Day<select name="weekday"><?php foreach($days as $number=>$day): ?><option value="<?= $number ?>"><?= h($day) ?></option><?php endforeach; ?></select></label><label>Period number<input type="number" name="period_number" min="1" max="12" required></label><label>Starts<input type="time" name="starts_at" required></label><label>Ends<input type="time" name="ends_at" required></label><label>Room / venue<input name="venue" maxlength="80" placeholder="Optional"></label><button class="primary-button">Add period</button></form><?php endif; ?></section><?php endif; ?>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Form <?= (int)$class['form_level'] ?><?= h($class['stream']) ?> · <?= h($term['name']) ?> <?= (int)$term['academic_year'] ?></h2><p><?= count($slots) ?> periods scheduled</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Day</th><th>Period</th><th>Time</th><th>Subject</th><th>Teacher</th><th>Venue</th><?php if($canManage): ?><th></th><?php endif; ?></tr></thead><tbody><?php foreach($slots as $slot): ?><tr><td><?= h($days[(int)$slot['weekday']]??'Day') ?></td><td><?= (int)$slot['period_number'] ?></td><td><?= h(substr($slot['starts_at'],0,5)) ?>–<?= h(substr($slot['ends_at'],0,5)) ?></td><td><b><?= h($slot['subject_name']) ?></b><small class="muted-cell"><?= h($slot['subject_code']) ?></small></td><td><?= h($slot['teacher_name']?:'Unassigned') ?></td><td><?= h($slot['venue']?:'—') ?></td><?php if($canManage): ?><td><form method="post" action="actions/timetable_slot_save.php"><?= csrf_field() ?><input type="hidden" name="operation" value="delete"><input type="hidden" name="slot_id" value="<?= (int)$slot['id'] ?>"><input type="hidden" name="term_id" value="<?= (int)$termId ?>"><input type="hidden" name="class_id" value="<?= (int)$classId ?>"><button class="text-button">Remove</button></form></td><?php endif; ?></tr><?php endforeach; if(!$slots): ?><tr><td colspan="<?= $canManage?7:6 ?>" class="empty-cell">No timetable periods are set for this class and term.</td></tr><?php endif; ?></tbody></table></div></section>
<?php endif; ?><?php endif; ?>
